import * as React from "react";

export type GrooveRingsIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function GrooveRingsIcon({ size = 20, ...props }: GrooveRingsIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5" /><circle cx="12" cy="12" r="6" /><circle cx="12" cy="12" r="1.5" />
    </svg>
  );
}
